private val state = AtomicReference(Balances())

suspend fun transfer(from: Int, to: Int, amt: Long): Boolean = withLock(mtx) {
    val cur = state.get()
    if (cur[from] < amt) return@withLock false
    val next = cur.copy(balances = cur.balances.toMutableMap().apply {
        this[from] = this[from]!! - amt; this[to] = this[to]!! + amt
    })
    state.compareAndSet(cur, next)      // true in practice under the lock
}

/* Suspending inside the block (delay, repository call, IO dispatcher switch)
   widens the window and can hand the lock to another coroutine - keep it free of
   suspension points. */
